<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\Auth;use App\Core\Csrf;use App\Core\RateLimiter;use App\Core\View;use App\Models\PlayerProfile;use App\Models\Team;use App\Models\TeamFinder;use RuntimeException;
final class TeamFinderController
{
    public function index(): void{Auth::requireLogin();$uid=(int)Auth::id();$managed=Team::managedTeamsForUser($uid);$teamId=(int)($_GET['team_id']??($managed[0]['id']??0));$players=$teamId>0?TeamFinder::playersForTeam($teamId,$_GET):[];View::render('team-finder/index',['title'=>'Takım Bul','matches'=>TeamFinder::teamsForPlayer($uid,$_GET),'profile'=>TeamFinder::profile($uid),'invites'=>TeamFinder::incomingInvites($uid),'managedTeams'=>$managed,'selectedTeamId'=>$teamId,'candidatePlayers'=>$players,'filters'=>$_GET]);}
    public function profileForm(): void{Auth::requireLogin();$base=\App\Models\User::accountDetails((int)Auth::id())?:[];View::render('team-finder/profile',['title'=>'Takım Arıyorum','profile'=>array_merge(['province'=>$base['province']??'','district'=>$base['district']??'','primary_position'=>$base['primary_position']??'','secondary_position'=>$base['secondary_position']??'','desired_level'=>'','availability_text'=>'','bio'=>'','status'=>'active'],TeamFinder::profile((int)Auth::id())?:[]),'errors'=>[]]);}
    public function saveProfile(): void{Auth::requireLogin();if(!Csrf::validate($_POST['_csrf']??null)){\App\Core\HttpError::render(419);return;}$e=TeamFinder::validateProfile($_POST);if($e!==[]){View::render('team-finder/profile',['title'=>'Takım Arıyorum','profile'=>$_POST,'errors'=>$e]);return;}TeamFinder::saveProfile((int)Auth::id(),$_POST);$_SESSION['flash_success']='Takım arama profilin güncellendi.';header('Location: /takim-bul');}
    public function invite(array $p): void{Auth::requireLogin();if(!Csrf::validate($_POST['_csrf']??null)){\App\Core\HttpError::render(419);return;}$actor=(int)Auth::id();if(!RateLimiter::allow(RateLimiter::clientKey('team_invite',(string)$actor),30,3600)){$_SESSION['flash_error']='Çok fazla takım daveti gönderdin. Bir süre sonra tekrar dene.';}else{try{TeamFinder::invite((int)($p['teamId']??0),$actor,(int)($p['userId']??0),(string)($_POST['message']??''));$_SESSION['flash_success']='Takım daveti gönderildi.';}catch(RuntimeException $e){$_SESSION['flash_error']=$e->getMessage();}}$return=(string)($_POST['return_to']??'/takim-bul');if(!str_starts_with($return,'/takim-bul'))$return='/takim-bul';header('Location: '.$return);}
    public function respond(array $p): void{Auth::requireLogin();if(!Csrf::validate($_POST['_csrf']??null)){\App\Core\HttpError::render(419);return;}try{TeamFinder::respond((int)($p['id']??0),(int)Auth::id(),(string)($_POST['status']??''));$_SESSION['flash_success']='Takım daveti yanıtlandı.';}catch(RuntimeException $e){$_SESSION['flash_error']=$e->getMessage();}header('Location: /takim-bul');}
}
